-- Trace v2 DEV4 audit integrity hotfix. Additive, idempotent and safe with existing R50/R55.
-- Audit is generated by SQLite in the same transaction as the successful CAS UPDATE.
CREATE TRIGGER IF NOT EXISTS trg_pro_trace_dev4_incident_audit_update
AFTER UPDATE OF status, note, fix_commit, revision ON pro_trace_dev4_incidents
FOR EACH ROW WHEN NEW.revision=OLD.revision+1
BEGIN
 INSERT INTO pro_trace_dev4_audit(fingerprint,status,note,fix_commit,revision,happened_at)
 VALUES(NEW.fingerprint,NEW.status,NEW.note,NEW.fix_commit,NEW.revision,NEW.updated_at);
END;
